import pandas as pd
import numpy as np

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_positions = inputs["target_positions"].copy()
    position_events = inputs["position_events"].copy()

    # Ensure target_positions has the right structure
    if target_positions.empty:
        target_positions = pd.DataFrame(columns=['account_id', 'symbol', 'qty', 'price', 'row_version'])

    # Ensure position_events has the right structure
    if position_events.empty:
        position_events = pd.DataFrame(columns=['batch_seq', 'account_id', 'symbol', 'op', 'qty', 'price', 'row_version'])

    # Step 1: Deduplicate events by batch_seq (keep first occurrence)
    position_events = position_events.drop_duplicates(subset=['batch_seq'], keep='first').reset_index(drop=True)

    # Step 2: Apply replay guard
    # For each (account_id, symbol) in target_positions, filter out events with row_version <= current row_version
    if not target_positions.empty:
        target_dict = {}
        for _, row in target_positions.iterrows():
            key = (row['account_id'], row['symbol'])
            target_dict[key] = row['row_version']

        # Filter events: keep only those where there's no row in target OR row_version > target's row_version
        def should_keep_event(event_row):
            key = (event_row['account_id'], event_row['symbol'])
            if key in target_dict:
                return event_row['row_version'] > target_dict[key]
            return True

        position_events = position_events[position_events.apply(should_keep_event, axis=1)].reset_index(drop=True)

    # Step 3: Sort events by row_version, then batch_seq
    position_events = position_events.sort_values(by=['row_version', 'batch_seq'], na_position='last').reset_index(drop=True)

    # Step 4: Apply events to target_positions
    # Create a working copy of target_positions indexed by (account_id, symbol)
    state = {}
    if not target_positions.empty:
        for _, row in target_positions.iterrows():
            key = (row['account_id'], row['symbol'])
            state[key] = {
                'qty': row['qty'],
                'price': row['price'],
                'row_version': row['row_version']
            }

    closed_positions_dict = {}  # (account_id, symbol) -> closed_version

    for _, event in position_events.iterrows():
        key = (int(event['account_id']), event['symbol'])
        op = event['op']
        event_qty = event['qty']
        event_price = event['price']
        event_row_version = int(event['row_version'])

        # Check if qty is 0 (close condition for I/U)
        is_close = (op in ['I', 'U']) and (pd.isna(event_qty) or event_qty == 0)

        if op == 'D' or is_close:
            # Remove the row if it exists
            if key in state:
                del state[key]
                closed_positions_dict[key] = event_row_version
            # If row doesn't exist, do nothing (but don't record a close)
        else:  # op == 'I' or op == 'U'
            if key in state:
                # Update existing row
                state[key]['qty'] = int(event_qty) if not pd.isna(event_qty) else state[key]['qty']
                # For U with NULL price, keep existing price; for I, use event price
                if op == 'U' and pd.isna(event_price):
                    # Keep existing price
                    pass
                else:
                    state[key]['price'] = event_price if not pd.isna(event_price) else None
                state[key]['row_version'] = event_row_version
            else:
                # Create new row
                state[key] = {
                    'qty': int(event_qty) if not pd.isna(event_qty) else event_qty,
                    'price': event_price if not pd.isna(event_price) else None,
                    'row_version': event_row_version
                }

    # Step 5: Build output DataFrames
    new_positions_rows = []
    for (account_id, symbol), data in state.items():
        new_positions_rows.append({
            'account_id': account_id,
            'symbol': symbol,
            'qty': data['qty'],
            'price': data['price'],
            'row_version': data['row_version']
        })

    if new_positions_rows:
        new_positions = pd.DataFrame(new_positions_rows)
        new_positions = new_positions[['account_id', 'symbol', 'qty', 'price', 'row_version']]
    else:
        new_positions = pd.DataFrame(columns=['account_id', 'symbol', 'qty', 'price', 'row_version'])

    closed_positions_rows = []
    for (account_id, symbol), closed_version in closed_positions_dict.items():
        closed_positions_rows.append({
            'account_id': account_id,
            'symbol': symbol,
            'closed_version': closed_version
        })

    if closed_positions_rows:
        closed_positions = pd.DataFrame(closed_positions_rows)
        closed_positions = closed_positions[['account_id', 'symbol', 'closed_version']]
    else:
        closed_positions = pd.DataFrame(columns=['account_id', 'symbol', 'closed_version'])

    # Ensure correct data types
    if not new_positions.empty:
        new_positions['account_id'] = new_positions['account_id'].astype('int64')
        new_positions['symbol'] = new_positions['symbol'].astype('str')
        new_positions['qty'] = new_positions['qty'].astype('int64')
        new_positions['price'] = new_positions['price'].astype('float64')
        new_positions['row_version'] = new_positions['row_version'].astype('int64')

    if not closed_positions.empty:
        closed_positions['account_id'] = closed_positions['account_id'].astype('int64')
        closed_positions['symbol'] = closed_positions['symbol'].astype('str')
        closed_positions['closed_version'] = closed_positions['closed_version'].astype('int64')

    return {
        'new_positions': new_positions,
        'closed_positions': closed_positions
    }
